// package.json: { "type": "module" }
import { readFile } from 'node:fs/promises';

const text = await readFile(new URL('./message.txt', import.meta.url), 'utf8');
console.log(text);

const response = await fetch('https://nodejs.org/api/documentation.json', {
  signal: AbortSignal.timeout(5000),
});

if (!response.ok) {
  throw new Error(`HTTP ${response.status}`);
}

const data = await response.json();
console.log(data);

import { createServer } from 'node:http';

const server = createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.write('Hello, ');
  res.end('world!\n');
});

server.listen(8000);

import process from 'node:process';

process.on('SIGTERM', () => {
  console.error('shutdown requested');
  process.exitCode = 0;
});

process.on('uncaughtException', (error) => {
  console.error(error);
  process.exitCode = 1;
});

console.log('running; press Ctrl-C or send SIGTERM');

import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';

await pipeline(
  createReadStream('input.bin'),
  createWriteStream('output.bin')
);

import { Readable, Writable } from 'node:stream';

const source = Readable.from(['one\n', 'two\n', 'three\n']);
const sink = new Writable({
  write(chunk, _encoding, callback) {
    process.stdout.write(chunk);
    setTimeout(callback, 50);
  }
});

source.pipe(sink);

import { Transform } from 'node:stream';

const upper = new Transform({
  transform(chunk, encoding, callback) {
    callback(null, chunk.toString().toUpperCase());
  }
});

upper.on('data', chunk => process.stdout.write(chunk));
upper.end('hello, transform streams!\n');

const { Buffer } = require('node:buffer');

const encoded = Buffer.from('Node.js', 'utf8');
console.log(encoded.toString('hex'));
console.log(encoded.toString('utf8'));

const safe = Buffer.alloc(4);
safe.writeUInt32BE(0x12345678);
console.log(safe.toString('hex'));

import { execFile } from 'node:child_process';

const child = execFile(process.execPath, ['-e', 'console.log("hello")']);
child.stdout.on('data', (chunk) => process.stdout.write(chunk));
child.stderr.on('data', (chunk) => process.stderr.write(chunk));
child.on('error', (error) => console.error('spawn failed:', error.message));
child.on('close', (code, signal) => {
  console.log(`closed: code=${code ?? 'null'} signal=${signal ?? 'null'}`);
});

