example.code:
import { EventEmitter } from 'node:events';

const bus = new EventEmitter();
const onReady = (name) => console.log(`${name} is ready`);

bus.once('ready', onReady);
bus.emit('ready', 'worker');
bus.emit('ready', 'worker');

bus.on('error', (error) => console.error(error.message));
bus.emit('error', new Error('temporary failure'));
